<?php
declare(strict_types=1);

function settlementMinutes(mixed $hours): int { return max(0,(int)round((float)$hours*60)); }
function settlementHours(int $minutes): float { return round(max(0,$minutes)/60,4); }
function settlementPackageMinutes(array $package,string $name): int {
    $minuteKey=$name.'_minutes';$quantityKey=$name.'_quantity';
    return array_key_exists($minuteKey,$package)&&$package[$minuteKey]!==null?max(0,(int)$package[$minuteKey]):settlementMinutes($package[$quantityKey]??0);
}
function settlementLedgerMinutes(PDO $pdo,int $bookingId,int $packageId): int {
    $stmt=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN movement_type='hold' THEN COALESCE(quantity_minutes,ROUND(quantity*60)) WHEN movement_type IN ('release','consume') THEN -COALESCE(quantity_minutes,ROUND(quantity*60)) ELSE 0 END),0) FROM package_usage_ledger WHERE booking_id=? AND client_package_id=?");
    $stmt->execute([$bookingId,$packageId]);return max(0,(int)round((float)$stmt->fetchColumn()));
}
function settlementCanonical(mixed $value): mixed {
    if(!is_array($value))return $value;
    if(array_is_list($value))return array_map('settlementCanonical',$value);
    ksort($value);foreach($value as $key=>$item)$value[$key]=settlementCanonical($item);return $value;
}
function settlementHash(array $value): string { return hash('sha256',json_encode(settlementCanonical($value),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); }

function studioSettlementPreview(PDO $pdo,array $user,int $bookingId,int $actualMinutes,bool $lock=false): array {
    if($actualMinutes<1)fail('حدد مدة تصوير صحيحة بالدقائق، دقيقة واحدة على الأقل.',422,'invalid_actual_duration');
    $lockSql=$lock?' FOR UPDATE':'';
    $stmt=$pdo->prepare("SELECT b.*,cp.billing_unit,cp.purchased_quantity,cp.purchased_minutes,cp.held_quantity,cp.held_minutes,cp.consumed_quantity,cp.consumed_minutes,cp.overage_price_snapshot,cp.service_id AS package_service_id,cp.name AS package_name FROM bookings b LEFT JOIN client_packages cp ON cp.id=b.client_package_id AND cp.organization_id=b.organization_id WHERE b.id=? AND b.organization_id=?$lockSql");
    $stmt->execute([$bookingId,$user['organization_id']]);$booking=$stmt->fetch();if(!$booking)fail('الحجز غير موجود.',404,'booking_not_found');
    $stmt=$pdo->prepare("SELECT * FROM booking_sessions WHERE booking_id=? AND organization_id=?$lockSql");$stmt->execute([$bookingId,$user['organization_id']]);$session=$stmt->fetch();if(!$session)fail('لا توجد جلسة تصوير لهذا الحجز.',404,'session_not_found');if($session['status']!=='active')fail('جلسة التصوير لم تعد نشطة.',409,'invalid_session_state');
    $unit=(string)($booking['billing_unit']??'hour');$packageId=(int)($booking['client_package_id']??0);$heldMinutes=$packageId?settlementLedgerMinutes($pdo,$bookingId,$packageId):0;
    if($packageId&&$heldMinutes<1)fail('لا يوجد رصيد محجوز صالح لهذا الموعد.',409,'missing_package_hold');
    $freeOriginal=0;$covered=$actualMinutes;$excess=0;
    if($unit==='hour'&&$packageId){
        $freeOriginal=max(0,settlementPackageMinutes($booking,'purchased')-settlementPackageMinutes($booking,'consumed')-settlementPackageMinutes($booking,'held'));
        $covered=min($actualMinutes,$heldMinutes+$freeOriginal);$excess=max(0,$actualMinutes-$covered);
    }
    $today=cairoNow()->format('Y-m-d');$eligible=[];
    if($excess>0){
        $sql="SELECT id,name,service_id,purchased_quantity,purchased_minutes,consumed_quantity,consumed_minutes,held_quantity,held_minutes,expires_at FROM client_packages WHERE organization_id=? AND client_id=? AND id<>? AND billing_unit='hour' AND status='active' AND starts_at<=? AND expires_at>=? ORDER BY id$lockSql";
        $other=$pdo->prepare($sql);$other->execute([$user['organization_id'],$booking['client_id'],$packageId,$today,$today]);
        foreach($other->fetchAll() as $row){$free=max(0,settlementPackageMinutes($row,'purchased')-settlementPackageMinutes($row,'consumed')-settlementPackageMinutes($row,'held'));if($free>=$excess)$eligible[]=['id'=>(int)$row['id'],'name'=>$row['name'],'service_id'=>(int)$row['service_id'],'free_minutes'=>$free,'remaining_after_minutes'=>$free-$excess,'expires_at'=>$row['expires_at']];}
    }
    $templates=$pdo->prepare("SELECT id,name,total_hours,validity_days,price,overage_price FROM services WHERE organization_id=? AND billing_unit='hour' AND is_active=1 ORDER BY name");$templates->execute([$user['organization_id']]);$packageTemplates=array_map(fn($row)=>['id'=>(int)$row['id'],'name'=>$row['name'],'total_minutes'=>settlementMinutes($row['total_hours']),'validity_days'=>(int)$row['validity_days'],'price'=>packageMoney(packageMoneyCents($row['price'])),'overage_rate'=>packageMoney(packageMoneyCents($row['overage_price']))],$templates->fetchAll());
    $rate=packageMoney(packageMoneyCents($booking['overage_price_snapshot']??0));if($rate<=0&&!empty($booking['service_id'])){$rateStmt=$pdo->prepare('SELECT overage_price FROM services WHERE id=? AND organization_id=? AND is_active=1');$rateStmt->execute([$booking['service_id'],$user['organization_id']]);$rate=packageMoney(packageMoneyCents($rateStmt->fetchColumn()?:0));}
    $version=max(1,(int)($session['settlement_version']??1));$snapshot=['session_id'=>(int)$session['id'],'session_version'=>$version,'actual_minutes'=>$actualMinutes,'held_minutes'=>$heldMinutes,'free_original_minutes'=>$freeOriginal,'covered_minutes'=>$covered,'excess_minutes'=>$excess,'package_id'=>$packageId,'package_minutes'=>[$packageId?settlementPackageMinutes($booking,'purchased'):0,$packageId?settlementPackageMinutes($booking,'consumed'):0,$packageId?settlementPackageMinutes($booking,'held'):0],'eligible'=>array_map(fn($row)=>[$row['id'],$row['free_minutes']],$eligible),'rate'=>$rate];
    return ['booking'=>$booking,'session'=>$session,'actual_minutes'=>$actualMinutes,'held_for_booking_minutes'=>$heldMinutes,'free_unheld_original_minutes'=>$freeOriginal,'covered_minutes'=>$covered,'excess_minutes'=>$excess,'eligible_packages'=>$eligible,'package_templates'=>$packageTemplates,'overage_rate'=>$rate,'default_mode'=>$eligible?'existing_package':($rate>0?'package_overage':'custom_invoice'),'session_version'=>$version,'preview_hash'=>settlementHash($snapshot)];
}

function settlementCreateInvoice(PDO $pdo,array $user,array $booking,string $description,int $cents,?int $projectId=null): int {
    $number='SET-'.cairoNow()->format('ymdHis').'-'.$booking['id'].'-'.random_int(10,99);$amount=packageMoney($cents);$today=cairoNow()->format('Y-m-d');
    $stmt=$pdo->prepare("INSERT INTO invoices (organization_id,client_id,project_id,invoice_number,status,subtotal,discount,total,paid_amount,issued_at,due_at,notes,created_by) VALUES (?,?,?,?,'issued',?,0,?,0,?,?,?,?)");$stmt->execute([$user['organization_id'],$booking['client_id'],$projectId,$number,$amount,$amount,$today,$today,$description,$user['id']]);$invoiceId=(int)$pdo->lastInsertId();
    $pdo->prepare('INSERT INTO invoice_items (invoice_id,service_id,description,quantity,unit,unit_price,total) VALUES (?,?,?,?,?,?,?)')->execute([$invoiceId,$booking['service_id']?:null,$description,1,'session',$amount,$amount]);return $invoiceId;
}

