        if($targetId&&in_array($mode,['new_package','existing_package'],true)){$targetPurchased=settlementPackageMinutes($targetPackage,'purchased');$targetConsumed=settlementPackageMinutes($targetPackage,'consumed');$targetHeld=settlementPackageMinutes($targetPackage,'held');$targetNewConsumed=$targetConsumed+$excess;if($targetNewConsumed+$targetHeld>$targetPurchased)fail('رصيد الباقة المستهدفة لم يعد كافيًا.',409,'settlement_balance_changed');$pdo->prepare('UPDATE client_packages SET consumed_minutes=?,consumed_quantity=? WHERE id=?')->execute([$targetNewConsumed,settlementHours($targetNewConsumed),$targetId]);$pdo->prepare("INSERT IGNORE INTO package_usage_ledger (client_package_id,booking_id,movement_type,quantity,quantity_minutes,reason,event_key,created_by) VALUES (?,?,'consume',?,?,'تسوية وقت تصوير زائد',?,?)")->execute([$targetId,$bookingId,settlementHours($excess),$excess,'settlement:'.$settlementId.':target',$user['id']]);}
        $ended=cairoNow()->format('Y-m-d H:i:s');$billableQuantity=$unit==='reel'?$reels:settlementHours($billable);$pdo->prepare("UPDATE booking_sessions SET ended_at=?,actual_seconds=?,billable_quantity=?,status='completed',ended_by=?,adjustment_reason=?,settlement_version=settlement_version+1 WHERE id=?")->execute([$ended,$actual*60,$billableQuantity,$user['id'],trim((string)($payload['reason']??''))?:null,$session['id']]);$pdo->prepare("UPDATE bookings SET status='completed',timer_ended_at=?,actual_seconds=?,actual_hours=?,actual_reels=?,billable_quantity=?,overage_quantity=?,overage_amount=?,session_version=session_version+1 WHERE id=?")->execute([$ended,$actual*60,settlementHours($actual),$reels,$billableQuantity,settlementHours($excess),$mode==='package_overage'?$due:0,$bookingId]);releaseBookingSlots($pdo,$bookingId);
        $outcome=$mode==='waive'?'تمت تسوية الوقت الإضافي دون رسوم':($excess?'تمت تسوية الوقت الإضافي وإضافته إلى حساب الخدمة':'اكتملت الجلسة ضمن الرصيد المتاح');appNotification($pdo,(int)$user['organization_id'],(int)$booking['client_id'],'client','session_completed','اكتملت جلسة التصوير',$outcome,'booking_sessions',(int)$session['id'],'session:'.$session['id'].':settlement','info');
        if($originalId)notifyPackagePaymentDue($pdo,(int)$user['organization_id'],(int)$booking['client_id'],$originalId,(string)$booking['client_name']);if($targetId)notifyPackagePaymentDue($pdo,(int)$user['organization_id'],(int)$booking['client_id'],$targetId,(string)$booking['client_name']);
        $response=['booking_id'=>$bookingId,'session_id'=>(int)$session['id'],'settlement_id'=>$settlementId,'status'=>'completed','actual_minutes'=>(int)$actual,'covered_minutes'=>$covered,'excess_minutes'=>$excess,'billable_minutes'=>$billable,'waived_minutes'=>$waived,'settlement_mode'=>$mode,'target_package_id'=>$targetId,'invoice_id'=>$invoiceId,'project_id'=>$projectId,'payment_id'=>$paymentId,'amount_due'=>$due,'amount_paid'=>$paid,'billing_unit'=>$unit];$pdo->prepare('UPDATE session_settlements SET response_json=? WHERE id=?')->execute([json_encode($response,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$settlementId]);audit($pdo,$user,'session_settle_and_complete','booking_sessions',(int)$session['id'],$session,$response+['client_id'=>(int)$booking['client_id']]);$pdo->commit();return $response;
